/* e36100Driver.cpp - asyn port driver for Keysight E36100B series DC power supply (E36103B 20 V / 2 A)
 * Generated by the ARGUS IOC engineer (ioc_scaffold_module) from the module's description.
 *
 * The device is reached through an asyn octet port (drvAsynIPPortConfigure or drvAsynSerialPortConfigure, with
 * its terminators set by asynOctetSetInputEos/asynOctetSetOutputEos). A thread polls every readback each
 * pollPeriod seconds; writing a setpoint record sends its command at once.
 *
 *   e36100Configure(portName, octetPort, pollPeriod, timeout)
 */
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#include <alarm.h>
#include <epicsStdio.h>
#include <epicsThread.h>
#include <iocsh.h>
#include <asynOctetSyncIO.h>

#include "e36100Driver.h"

#include <epicsExport.h>

static const char *driverName = "e36100Driver";

static void pollC(void *drv)
{
    static_cast<E36100Driver *>(drv)->poll();
}

E36100Driver::E36100Driver(const char *portName, const char *octetPort, double pollPeriod, double timeout)
    : asynPortDriver(portName, 1,
                     asynInt32Mask | asynFloat64Mask | asynOctetMask | asynDrvUserMask,
                     asynInt32Mask | asynFloat64Mask | asynOctetMask,
                     ASYN_CANBLOCK, 1, 0, 0),
      octet_(NULL), pollPeriod_(pollPeriod > 0 ? pollPeriod : 1.0),
      timeout_(timeout > 0 ? timeout : 2.0)
{
    createParam("CONNECTED", asynParamInt32, &P_Connected);
    createParam("Voltage_RB", asynParamFloat64, &P_Voltage_RB);
    createParam("Voltage_SP", asynParamFloat64, &P_Voltage_SP);
    createParam("VoltageSet_RB", asynParamFloat64, &P_VoltageSet_RB);
    createParam("Current_RB", asynParamFloat64, &P_Current_RB);
    createParam("Current_SP", asynParamFloat64, &P_Current_SP);
    createParam("CurrentSet_RB", asynParamFloat64, &P_CurrentSet_RB);
    createParam("OVP_RB", asynParamFloat64, &P_OVP_RB);
    createParam("OVP_SP", asynParamFloat64, &P_OVP_SP);
    createParam("Output_RB", asynParamInt32, &P_Output_RB);
    createParam("Output_SP", asynParamInt32, &P_Output_SP);
    createParam("Ident_RB", asynParamOctet, &P_Ident_RB);
    createParam("Error_RB", asynParamOctet, &P_Error_RB);
    setIntegerParam(P_Connected, 0);

    if (pasynOctetSyncIO->connect(octetPort, 0, &octet_, NULL) != asynSuccess) {
        asynPrint(pasynUserSelf, ASYN_TRACE_ERROR, "%s: cannot connect to octet port %s\n", driverName, octetPort);
        octet_ = NULL;
        return;
    }
    epicsThreadCreate(portName, epicsThreadPriorityMedium, epicsThreadGetStackSize(epicsThreadStackMedium),
                      pollC, this);
}

/* One query and its reply, or one command without a reply when in is NULL. */
asynStatus E36100Driver::command(const char *out, char *in, size_t inSize)
{
    size_t nWrite = 0, nRead = 0;
    int eom = 0;
    asynStatus status;

    if (!octet_) return asynDisconnected;
    if (!in) return pasynOctetSyncIO->write(octet_, out, strlen(out), timeout_, &nWrite);
    in[0] = '\0';
    status = pasynOctetSyncIO->writeRead(octet_, out, strlen(out), in, inSize - 1, timeout_, &nWrite, &nRead, &eom);
    in[status == asynSuccess ? nRead : 0] = '\0';
    return status;
}

/* A setpoint's command, and its acknowledgement when the device sends one. */
asynStatus E36100Driver::send(const char *out, const char *ack)
{
    char in[256];
    asynStatus status;

    if (!ack) return command(out, NULL, 0);
    status = command(out, in, sizeof(in));
    if (status == asynSuccess && strcmp(in, ack) != 0) {
        asynPrint(pasynUserSelf, ASYN_TRACE_ERROR, "%s: '%s' answered '%s', not '%s'\n", driverName, out, in, ack);
        status = asynError;
    }
    return status;
}

void E36100Driver::failed(int param)
{
    setParamStatus(param, asynError);
    setParamAlarmStatus(param, COMM_ALARM);
    setParamAlarmSeverity(param, INVALID_ALARM);
}

void E36100Driver::poll()
{
    char in[256];
    int answered;

    while (1) {
        answered = 0;
        lock();
        /* Voltage: MEAS:VOLT? -> %f */
        if (command("MEAS:VOLT?", in, sizeof(in)) == asynSuccess) {
            double v;
            if (sscanf(in, "%lf", &v) == 1) {
                setDoubleParam(P_Voltage_RB, v);
                setParamStatus(P_Voltage_RB, asynSuccess);
                setParamAlarmStatus(P_Voltage_RB, NO_ALARM);
                setParamAlarmSeverity(P_Voltage_RB, NO_ALARM);
                answered = 1;
            } else {
                asynPrint(pasynUserSelf, ASYN_TRACE_ERROR, "%s: cannot read %s from reply '%s'\n",
                          driverName, "Voltage", in);
                failed(P_Voltage_RB);
            }
        } else {
            failed(P_Voltage_RB);
        }
        /* VoltageSet: VOLT? -> %f */
        if (command("VOLT?", in, sizeof(in)) == asynSuccess) {
            double v;
            if (sscanf(in, "%lf", &v) == 1) {
                setDoubleParam(P_VoltageSet_RB, v);
                setParamStatus(P_VoltageSet_RB, asynSuccess);
                setParamAlarmStatus(P_VoltageSet_RB, NO_ALARM);
                setParamAlarmSeverity(P_VoltageSet_RB, NO_ALARM);
                answered = 1;
            } else {
                asynPrint(pasynUserSelf, ASYN_TRACE_ERROR, "%s: cannot read %s from reply '%s'\n",
                          driverName, "VoltageSet", in);
                failed(P_VoltageSet_RB);
            }
        } else {
            failed(P_VoltageSet_RB);
        }
        /* Current: MEAS:CURR? -> %f */
        if (command("MEAS:CURR?", in, sizeof(in)) == asynSuccess) {
            double v;
            if (sscanf(in, "%lf", &v) == 1) {
                setDoubleParam(P_Current_RB, v);
                setParamStatus(P_Current_RB, asynSuccess);
                setParamAlarmStatus(P_Current_RB, NO_ALARM);
                setParamAlarmSeverity(P_Current_RB, NO_ALARM);
                answered = 1;
            } else {
                asynPrint(pasynUserSelf, ASYN_TRACE_ERROR, "%s: cannot read %s from reply '%s'\n",
                          driverName, "Current", in);
                failed(P_Current_RB);
            }
        } else {
            failed(P_Current_RB);
        }
        /* CurrentSet: CURR? -> %f */
        if (command("CURR?", in, sizeof(in)) == asynSuccess) {
            double v;
            if (sscanf(in, "%lf", &v) == 1) {
                setDoubleParam(P_CurrentSet_RB, v);
                setParamStatus(P_CurrentSet_RB, asynSuccess);
                setParamAlarmStatus(P_CurrentSet_RB, NO_ALARM);
                setParamAlarmSeverity(P_CurrentSet_RB, NO_ALARM);
                answered = 1;
            } else {
                asynPrint(pasynUserSelf, ASYN_TRACE_ERROR, "%s: cannot read %s from reply '%s'\n",
                          driverName, "CurrentSet", in);
                failed(P_CurrentSet_RB);
            }
        } else {
            failed(P_CurrentSet_RB);
        }
        /* OVP: VOLT:PROT? -> %f */
        if (command("VOLT:PROT?", in, sizeof(in)) == asynSuccess) {
            double v;
            if (sscanf(in, "%lf", &v) == 1) {
                setDoubleParam(P_OVP_RB, v);
                setParamStatus(P_OVP_RB, asynSuccess);
                setParamAlarmStatus(P_OVP_RB, NO_ALARM);
                setParamAlarmSeverity(P_OVP_RB, NO_ALARM);
                answered = 1;
            } else {
                asynPrint(pasynUserSelf, ASYN_TRACE_ERROR, "%s: cannot read %s from reply '%s'\n",
                          driverName, "OVP", in);
                failed(P_OVP_RB);
            }
        } else {
            failed(P_OVP_RB);
        }
        /* Output: OUTP? -> %d */
        if (command("OUTP?", in, sizeof(in)) == asynSuccess) {
            int v;
            if (sscanf(in, "%d", &v) == 1) {
                setIntegerParam(P_Output_RB, v);
                setParamStatus(P_Output_RB, asynSuccess);
                setParamAlarmStatus(P_Output_RB, NO_ALARM);
                setParamAlarmSeverity(P_Output_RB, NO_ALARM);
                answered = 1;
            } else {
                asynPrint(pasynUserSelf, ASYN_TRACE_ERROR, "%s: cannot read %s from reply '%s'\n",
                          driverName, "Output", in);
                failed(P_Output_RB);
            }
        } else {
            failed(P_Output_RB);
        }
        /* Ident: *IDN? -> %s */
        if (command("*IDN?", in, sizeof(in)) == asynSuccess) {
            char v[256];
            if (epicsSnprintf(v, sizeof(v), "%s", in) >= 0) {
                setStringParam(P_Ident_RB, v);
                setParamStatus(P_Ident_RB, asynSuccess);
                setParamAlarmStatus(P_Ident_RB, NO_ALARM);
                setParamAlarmSeverity(P_Ident_RB, NO_ALARM);
                answered = 1;
            } else {
                asynPrint(pasynUserSelf, ASYN_TRACE_ERROR, "%s: cannot read %s from reply '%s'\n",
                          driverName, "Ident", in);
                failed(P_Ident_RB);
            }
        } else {
            failed(P_Ident_RB);
        }
        /* Error: SYST:ERR? -> %s */
        if (command("SYST:ERR?", in, sizeof(in)) == asynSuccess) {
            char v[256];
            if (epicsSnprintf(v, sizeof(v), "%s", in) >= 0) {
                setStringParam(P_Error_RB, v);
                setParamStatus(P_Error_RB, asynSuccess);
                setParamAlarmStatus(P_Error_RB, NO_ALARM);
                setParamAlarmSeverity(P_Error_RB, NO_ALARM);
                answered = 1;
            } else {
                asynPrint(pasynUserSelf, ASYN_TRACE_ERROR, "%s: cannot read %s from reply '%s'\n",
                          driverName, "Error", in);
                failed(P_Error_RB);
            }
        } else {
            failed(P_Error_RB);
        }
        setIntegerParam(P_Connected, answered);
        callParamCallbacks();
        unlock();
        epicsThreadSleep(pollPeriod_);
    }
}

asynStatus E36100Driver::writeInt32(asynUser *pasynUser, epicsInt32 value)
{
    int function = pasynUser->reason;
    char out[256];
    const char *ack = NULL;
    if (function == P_Output_SP) {
        epicsSnprintf(out, sizeof(out), "OUTP %d", (int)value);
        ack = NULL;
    }
    else {
        return asynPortDriver::writeInt32(pasynUser, value);
    }
    asynStatus status = send(out, ack);
    setIntegerParam(function, value);
    callParamCallbacks();
    return status;
}

asynStatus E36100Driver::writeFloat64(asynUser *pasynUser, epicsFloat64 value)
{
    int function = pasynUser->reason;
    char out[256];
    const char *ack = NULL;
    if (function == P_Voltage_SP) {
        epicsSnprintf(out, sizeof(out), "VOLT %f", (double)value);
        ack = NULL;
    }
    else if (function == P_Current_SP) {
        epicsSnprintf(out, sizeof(out), "CURR %f", (double)value);
        ack = NULL;
    }
    else if (function == P_OVP_SP) {
        epicsSnprintf(out, sizeof(out), "VOLT:PROT %f", (double)value);
        ack = NULL;
    }
    else {
        return asynPortDriver::writeFloat64(pasynUser, value);
    }
    asynStatus status = send(out, ack);
    setDoubleParam(function, value);
    callParamCallbacks();
    return status;
}

/* iocsh: e36100Configure(portName, octetPort, pollPeriod, timeout) */
extern "C" int e36100Configure(const char *portName, const char *octetPort, double pollPeriod, double timeout)
{
    new E36100Driver(portName, octetPort, pollPeriod, timeout);
    return asynSuccess;
}

static const iocshArg configureArg0 = {"portName", iocshArgString};
static const iocshArg configureArg1 = {"octetPort", iocshArgString};
static const iocshArg configureArg2 = {"pollPeriod", iocshArgDouble};
static const iocshArg configureArg3 = {"timeout", iocshArgDouble};
static const iocshArg *const configureArgs[] = {&configureArg0, &configureArg1, &configureArg2, &configureArg3};
static const iocshFuncDef configureDef = {"e36100Configure", 4, configureArgs};

static void configureCall(const iocshArgBuf *args)
{
    e36100Configure(args[0].sval, args[1].sval, args[2].dval, args[3].dval);
}

static void e36100DriverRegister(void)
{
    iocshRegister(&configureDef, configureCall);
}

extern "C" {
epicsExportRegistrar(e36100DriverRegister);
}
